    div_rows = [r for r in range(h) if all(v == 3 for v in g[r])]
    div_cols = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    # Collect motif tiles from non-divider cells.
    tiles = []
    step = n + 1
    for r0 in range(0, h - n + 1, step):
        for c0 in range(0, w - n + 1, step):
            tile = [row[c0:c0+n] for row in g[r0:r0+n]]
            if any(v == 3 for row in tile for v in row):
                continue
            if any(v == 2 for row in tile for v in row):
                tiles.append((r0 // step, c0 // step, r0, c0, tile))
    # The recurrent motif is the most frequent tile; use it to fill the
    # corresponding central missing tile of the divider.
    from collections import Counter
    shapes = Counter(tuple(tuple(x for x in row) for row in t[4]) for t in tiles)
    motif = max(shapes, key=shapes.get) if shapes else None
    # Paint the coordinate-coded 2 in each occupied tile as 8.
    for tr, tc, r0, c0, tile in tiles:
        rr, cc = tr, tc
        if rr < n and cc < n and g[r0+rr][c0+cc] == 2:
            g[r0+rr][c0+cc] = 8
