        r0, c0 = r * pitch, c * pitch
        if r0 + n > h or c0 + n > w:
            return None
        return tuple(tuple(original[r0+i][c0:c0+n]) for i in range(n))

    def is_bar(t):
        return t is not None and all(v == 3 for row in t for v in row)

    # The identical tile is a stamp; its 2-cells indicate where copies are
    # present across the rectangular field, including in the separator band.
    candidates = []
    for r in range(nr):
        for c in range(nc):
            t = get_tile(r, c)
            if t is not None and not is_bar(t) and any(v == 2 for row in t for v in row):
                candidates.append(t)
    if not candidates:
        return out
    stamp = [list(row) for row in Counter(candidates).most_common(1)[0][0]]

    # Each colored 3 stripe removes only the 3s; it does not erase the stamp
    # field. Stamp its corresponding tile positions where the template has 2.
    divider_rows = [r for r in range(h) if all(v == 3 for v in original[r])]
    divider_cols = [c for c in range(w) if all(original[r][c] == 3 for r in range(h))]
    if divider_rows:
        for r in divider_rows:
            out[r] = [0] * w
        tr = divider_rows[0] // pitch
        for tc in range(nc):
            if tr < n and tc < n and stamp[tr][tc] == 2:
